/**
 * 2D strip animation for deployed cards.
 *
 * Strips are generated by `scripts/generate_sprite_strips.py` from the local
 * card art into `/public/sprites/<card>.png` (6 frames, 96x96):
 *   0-1 idle, 2-3 walk, 4 attack, 5 death.
 *
 * The loader is lazy and caches one Image per card. Missing strips return
 * false so the canvas can fall back to the original static card art.
 */

import { resolveCardArtId } from "../cardAliases";

export type SpriteState = "idle" | "walk" | "attack" | "death";

export const SPRITE_FRAME = 96;
export const SPRITE_FRAMES = 6;
const FPS: Record<SpriteState, number> = {
  idle: 2.4,
  walk: 9,
  attack: 12,
  death: 1,
};
const FRAME_INDEX: Record<SpriteState, readonly number[]> = {
  idle: [0, 1],
  walk: [2, 3],
  attack: [4],
  death: [5],
};

const cache = new Map<string, HTMLImageElement | "missing">();

export function preloadCardSprite(cardId: string): void {
  spriteImage(cardId);
}

function spriteImage(cardId: string): HTMLImageElement | null {
  if (typeof window === "undefined") return null;
  const slug = resolveCardArtId(cardId).replace(/[^a-z0-9-]/gi, "-").toLowerCase();
  const hit = cache.get(slug);
  if (hit !== undefined) return hit === "missing" ? null : hit;
  const img = new Image();
  img.decoding = "async";
  img.onerror = () => cache.set(slug, "missing");
  img.src = `/sprites/${slug}.png`;
  cache.set(slug, img);
  return img;
}

/**
 * Draw one animation frame centred at (0,0) in the current canvas space.
 * Returns false when no strip exists (caller should fall back to card art).
 * O(1): one drawImage, no allocations in the hot path.
 */
export function drawCardSprite(
  c: CanvasRenderingContext2D,
  cardId: string,
  state: SpriteState,
  nowMs: number,
  size: number,
  facing: 1 | -1 = 1,
  alpha = 1,
): boolean {
  const img = spriteImage(cardId);
  if (img === null || !img.complete || img.naturalWidth === 0) return false;
  const frames = FRAME_INDEX[state];
  const fps = FPS[state];
  const idx = frames[Math.floor((nowMs / 1000) * fps) % frames.length];
  c.save();
  c.globalAlpha = alpha;
  c.scale(facing, 1);
  c.drawImage(
    img,
    idx * SPRITE_FRAME,
    0,
    SPRITE_FRAME,
    SPRITE_FRAME,
    -size / 2,
    -size / 2,
    size,
    size,
  );
  c.restore();
  return true;
}
